 if(horses.some(h=>!integer(h.horse_no)||typeof h.horse_name!=='string'||!h.horse_name||!Array.isArray(h.past_runs))||new Set(horses.map(h=>h.horse_no)).size!==horses.length)throw Error('EYE_REVIEW_IDENTITY');
